'use strict';
window.OrthodoxStudyTools=(()=>{
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const blank=()=>({version:1,passages:[],highlights:[],revisit:[],questions:[],reviews:{},corrections:[],events:[]});
  let data=null,bridge=null,observer=null,selected=null,queued=false,activeParagraph=null;
  const key=()=>window.OrthodoxAccounts.storageKey('orthodox-way.study-tools.v1');
  const canonicalText=node=>window.OrthodoxSaintReferences?.canonicalText(node)??node.textContent;
  const hash=text=>{let n=2166136261;for(const char of text)n=Math.imul(n^char.charCodeAt(0),16777619);return (n>>>0).toString(36);};
  const id=()=>crypto.randomUUID();
  function validate(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw)||raw.version!==1)throw new Error('Unsupported or invalid study notebook. Your current notebook has not changed.');for(const field of ['passages','highlights','revisit','questions','corrections','events'])if(!Array.isArray(raw[field])||raw[field].some(item=>!item||typeof item!=='object'||Array.isArray(item)||typeof item.id!=='string'))throw new Error('The study notebook has an invalid '+field+' collection. Your current notebook has not changed.');if(!raw.reviews||typeof raw.reviews!=='object'||Array.isArray(raw.reviews))throw new Error('Invalid study review records. Your current notebook has not changed.');return true;}
  function sanitize(raw){const clean=blank();if(!raw||typeof raw!=='object')return clean;for(const field of ['passages','highlights','revisit','questions','corrections','events'])if(Array.isArray(raw[field]))clean[field]=raw[field].filter(v=>v&&typeof v==='object'&&typeof v.id==='string').slice(-10000).map(v=>{const out={};for(const [k,value]of Object.entries(v)){if(['__proto__','constructor','prototype'].includes(k))continue;if(typeof value==='string')out[k]=value.slice(0,100000);else if(typeof value==='number'&&Number.isFinite(value))out[k]=value;else if(typeof value==='boolean')out[k]=value;}return out;});if(raw.reviews&&typeof raw.reviews==='object')for(const [k,v]of Object.entries(raw.reviews))if(/^[a-z0-9-]+$/i.test(k)&&v&&typeof v==='object')clean.reviews[k]={lastReviewed:String(v.lastReviewed||'').slice(0,40),nextReview:String(v.nextReview||'').slice(0,40),count:Math.max(0,Math.min(10000,Number(v.count)||0))};return clean;}
  function get(){if(!data){try{data=sanitize(JSON.parse(localStorage.getItem(key())||'null'));}catch{data=blank();}}return data;}
  function save(){try{localStorage.setItem(key(),JSON.stringify(get()));window.OrthodoxAccounts.changed();}catch{bridge?.toast('Notebook could not be saved. Export a backup before closing this tab.');}}
  function replace(raw,{silent=false}={}){data=sanitize(raw);if(silent)localStorage.setItem(key(),JSON.stringify(data));else save();}
  function snapshot(){return JSON.parse(JSON.stringify(get()));}
  const route=()=>(window.OrthodoxSite?.route()||location.hash).split('?')[0]||'#/home';
  const title=()=>{const heading=document.querySelector('main h1')?.textContent||document.title,page=route(),selectors=page==='#/church'?['.church-step-header h2','[data-church-selected-part] > h2']:page==='#/authority'?['#authority-role-title','#authority-case-title']:[],labels=selectors.map(selector=>document.querySelector(selector)).filter(el=>el&&el.getClientRects().length).map(el=>el.textContent);return [heading,...new Set(labels)].join(' · ');};
  const date=()=>new Date().toISOString();
  const localRoute=value=>/^#\/[a-z0-9/-]+$/i.test(value)?value:'#/notebook';
  function guideContext(page=route(),query=(window.OrthodoxSite?.route()||location.hash).split('?')[1]||''){
    const keys=page==='#/church'?['mode','view','part','step']:page==='#/authority'?['view','role','case']:[];
    if(!keys.length)return '';const input=new URLSearchParams(query),output=new URLSearchParams();
    for(const key of keys){const value=input.get(key);if(value&&/^[a-z0-9-]{1,100}$/i.test(value))output.set(key,value);}return output.toString();
  }
  function link(item){const page=localRoute(item.route),query=new URLSearchParams(guideContext(page,item.context||''));if(item.anchor)query.set('passage',item.anchor);return page+(query.size?'?'+query:'');}
  function connect(value){bridge=value;observer=new MutationObserver(()=>schedule());observer.observe(document.getElementById('main'),{childList:true,subtree:true});document.addEventListener('selectionchange',()=>{const s=window.getSelection();if(!s||s.isCollapsed)return;const range=s.getRangeAt(0),p=(range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer.parentElement).closest('[data-study-anchor]');if(p&&p.contains(range.startContainer)&&p.contains(range.endContainer)){const before=document.createRange();before.selectNodeContents(p);before.setEnd(range.startContainer,range.startOffset);const start=canonicalText(before.cloneContents()).length,text=canonicalText(range.cloneContents());selected={anchor:p.dataset.studyAnchor,text,start,end:start+text.length};activate(p);}});document.addEventListener('click',event=>{const p=event.target.closest('[data-study-anchor]');if(p&&!event.target.closest('.glossary-reference,.scripture-reference,.scripture-assist,.saint-reference'))activate(p);action(event);});document.addEventListener('focusin',event=>{if(event.target.matches('[data-study-anchor]'))activate(event.target);});document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.matches('[data-study-anchor]')){event.preventDefault();activate(event.target);document.querySelector('#passage-selection-toolbar button')?.focus();}if(event.key==='Escape'&&document.querySelector('#passage-selection-toolbar')){const p=activeParagraph;document.querySelector('#passage-selection-toolbar').remove();activeParagraph=null;p?.classList.remove('passage-active');}});window.addEventListener(window.OrthodoxSite?'orthodox-page':'hashchange',()=>{document.querySelector('#passage-selection-toolbar')?.remove();activeParagraph=null;selected=null;});schedule();}
  function activate(p){activeParagraph?.classList.remove('passage-active');activeParagraph=p;p.classList.add('passage-active');let bar=document.querySelector('#passage-selection-toolbar');if(!bar){bar=document.createElement('div');bar.id='passage-selection-toolbar';bar.className='passage-selection-toolbar';bar.setAttribute('role','toolbar');bar.setAttribute('aria-label','Selected passage tools');document.body.append(bar);}const anchor=p.dataset.studyAnchor,saved=get().passages.some(x=>x.route===route()&&x.anchor===anchor);bar.innerHTML=`<span>Selected paragraph</span><button data-tool="passage" data-anchor="${anchor}" aria-pressed="${saved}">${saved?'Passage saved':'Save passage'}</button><button data-tool="highlight" data-anchor="${anchor}">Highlight selection</button><button data-tool="close-passage">Close</button>`;}
  function schedule(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;enhance();});}
  function enhance(){const root=document.getElementById('main');if(!root||!bridge)return;
    const page=route(),context=guideContext(),oldTools=root.querySelector('[data-page-tools]');if(oldTools&&(oldTools.dataset.guideContext||'')!==context)oldTools.remove();if((/^#\/(lesson|saint|service|term|prayer|icon)\//.test(page)||['#/church','#/authority'].includes(page))&&!root.querySelector('[data-page-tools]')){const header=root.querySelector('h1');if(header){const box=document.createElement('div');box.className='page-study-tools tool-actions';box.dataset.pageTools='true';box.dataset.guideContext=context;const saved=get().revisit.some(x=>x.route===page&&(x.context||'')===guideContext());box.innerHTML=`<button data-tool="revisit" aria-pressed="${saved}">${saved?'Saved to revisit':'Revisit later'}</button><button data-tool="question">Add a question</button><button data-tool="correction">Report a correction</button><a href="#/notebook">Notebook</a>`;const sourceSection=root.querySelector('.source-footnotes,#saint-sources,#icon-sources,#authority-sources,#church-sources,.church-guide-sources');if(sourceSection)(sourceSection.closest('.references-disclosure')||sourceSection).before(box);else (root.querySelector('.reader-layout>article,.saint-reader,.icon-reader,.prayer-reader')||root).append(box);}}
    const occurrences=new Map();for(const p of root.querySelectorAll('blockquote p,.native-prayer-text .prayer-paragraph p,[data-annotatable]')){if(p.closest('.scripture-preview,.study-tools-page')||!canonicalText(p).trim())continue;const text=canonicalText(p),scope=p.closest('[data-study-scope]')?.dataset.studyScope,base=hash(page+'|'+(scope?scope+'|':'')+text),n=(occurrences.get(base)||0)+1;occurrences.set(base,n);const anchor=base+'-'+n;if(p.dataset.studyAnchor)continue;p.dataset.studyAnchor=anchor;if(!p.id)p.id='passage-'+anchor;
      p.tabIndex=0;p.title='Select this paragraph; press Enter for passage tools.';applyHighlights(p);
    }
    const requested=new URLSearchParams((window.OrthodoxSite?.route()||location.hash).split('?')[1]||'').get('passage');if(requested&&root.dataset.passageRestored!==page+'|'+requested){const target=root.querySelector('[data-study-anchor="'+CSS.escape(requested)+'"]');if(target){root.dataset.passageRestored=page+'|'+requested;for(let ancestor=target.parentElement;ancestor;ancestor=ancestor.parentElement)if(ancestor.tagName==='DETAILS')ancestor.open=true;target.classList.add('passage-target');target.scrollIntoView();target.tabIndex=0;target.focus({preventScroll:true});}}if(!requested)delete root.dataset.passageRestored;
  }
  function applyHighlights(p){const spans=get().highlights.filter(x=>x.route===route()&&x.anchor===p.dataset.studyAnchor&&x.original===canonicalText(p)).sort((a,b)=>b.start-a.start);for(const item of spans){const walker=document.createTreeWalker(p,NodeFilter.SHOW_TEXT),nodes=[];let pos=0;while(walker.nextNode()){if(walker.currentNode.parentElement.closest('[data-saint-honorific]'))continue;nodes.push({node:walker.currentNode,start:pos,end:pos+walker.currentNode.length});pos+=walker.currentNode.length;}for(const part of nodes.reverse()){const start=Math.max(item.start,part.start)-part.start,end=Math.min(item.end,part.end)-part.start;if(start>=end||part.node.parentElement.closest('mark'))continue;const range=document.createRange();range.setStart(part.node,start);range.setEnd(part.node,end);const mark=document.createElement('mark');mark.className='study-highlight';range.surroundContents(mark);}}}
  function addQuestion(page=route(),heading=title()){const context=guideContext(page);dialog('Question','Your question',value=>{get().questions.push({id:id(),route:page,context,title:heading,text:value,createdAt:date(),answered:false});save();bridge.toast('Question saved privately in your notebook.');});}
  function dialog(heading,label,submit){const box=document.createElement('dialog');box.className='study-tool-dialog';box.innerHTML=`<form><h2>${esc(heading)}</h2><label>${esc(label)}<textarea name="text" maxlength="10000" required rows="6"></textarea></label><div class="tool-actions"><button class="primary">Save</button><button type="button" data-close>Cancel</button></div></form>`;document.body.append(box);box.querySelector('[data-close]').onclick=()=>box.close();box.addEventListener('close',()=>box.remove());box.querySelector('form').onsubmit=event=>{event.preventDefault();const text=box.querySelector('textarea').value.trim();if(text){submit(text);box.close();}};box.showModal();}
  async function action(event){const button=event.target.closest('[data-tool]');if(!button)return;const kind=button.dataset.tool,page=route();
    if(kind==='close-passage'){document.querySelector('#passage-selection-toolbar')?.remove();activeParagraph?.classList.remove('passage-active');activeParagraph=null;return;}
    if(kind==='revisit'){const list=get().revisit,context=guideContext(),found=list.find(x=>x.route===page&&(x.context||'')===context);if(found)get().revisit=list.filter(x=>x!==found);else list.push({id:id(),route:page,context,title:title(),createdAt:date()});save();button.textContent=found?'Revisit later':'Saved to revisit';button.setAttribute('aria-pressed',String(!found));}
    if(kind==='question')addQuestion();
    if(kind==='correction'){dialog('Report a correction','Describe the issue and identify the source or passage',text=>{get().corrections.push({id:id(),route:page,context:guideContext(),title:title(),text,createdAt:date(),status:'draft',review_note:''});save();bridge.toast('Correction draft saved. Submit it from Editorial review when accounts are connected.');});}
    if(kind==='passage'||kind==='highlight'){const anchor=button.dataset.anchor,p=document.querySelector('[data-study-anchor="'+CSS.escape(anchor)+'"]');if(!p)return;
      if(kind==='passage'){const found=get().passages.find(x=>x.route===page&&x.anchor===anchor);if(found)get().passages=get().passages.filter(x=>x!==found);else get().passages.push({id:id(),route:page,context:guideContext(),title:title(),anchor,text:canonicalText(p),createdAt:date()});save();button.textContent=found?'Save passage':'Passage saved';button.setAttribute('aria-pressed',String(!found));}
      else{if(!selected||selected.anchor!==anchor||!selected.text.trim()){bridge.toast('Select words in this paragraph, then choose Highlight selection.');return;}if(!get().highlights.some(x=>x.route===page&&x.anchor===anchor&&x.start===selected.start&&x.end===selected.end)){get().highlights.push({id:id(),route:page,context:guideContext(),title:title(),anchor,text:selected.text,original:canonicalText(p),start:selected.start,end:selected.end,createdAt:date()});save();applyHighlights(p);}window.getSelection().removeAllRanges();selected=null;}
    }
  }
  function mount({root,lessons=[],glossary,prayers=[],kind='notebook',sources=[]}){const abort=new AbortController(),on=(type,fn)=>root.addEventListener(type,fn,{signal:abort.signal});let tab='passages',query='',reviewIndex=0;
    function draw(){if(kind==='review'){drawReview();return;}const d=get();root.classList.add('study-tools-page');root.innerHTML='<h1>Study notebook</h1><p><a href="#/journal">Lesson notes and bookmarks</a> · <a href="#/review-cards">Review cards</a> · <a href="#/editorial">Correction drafts</a></p><label>Search notebook<input type="search" id="notebook-search" value="'+esc(query)+'"></label><div class="tool-tabs" role="group" aria-label="Notebook collection">'+[['passages','Saved passages'],['highlights','Highlights'],['revisit','Revisit later'],['questions','Questions']].map(([key,label])=>`<button data-notebook-tab="${key}" aria-pressed="${tab===key}">${label} (${d[key].length})</button>`).join('')+'</div><div id="notebook-items">'+items()+'</div><button data-new-question class="secondary">Add a question</button><p>These tools record your study activity. They do not assess spiritual maturity.</p>';}
    function items(){const list=get()[tab].filter(item=>[item.text,item.title].join(' ').toLowerCase().includes(query.toLowerCase()));return list.length?list.map(item=>`<article class="notebook-item"><h2><a href="${esc(link(item))}">${esc(item.title)}</a></h2>${item.text?`<p class="note-preview">${esc(item.text)}</p>`:''}${tab==='questions'?`<button data-answer="${esc(item.id)}" aria-pressed="${item.answered}">${item.answered?'Marked discussed':'Mark discussed'}</button>`:''}<button data-remove-item="${esc(item.id)}" class="text-button">Remove</button></article>`).join(''):'<p>No items in this collection.</p>';}
    const cards=[...(glossary?.terms||[]).filter(t=>t.definition.kind==='quotation').map(t=>({id:t.id,prompt:t.term,text:t.definition.text,route:'#/term/'+t.id,sourceId:t.definition.sourceId,locator:t.definition.locator})),...prayers.filter(p=>p.length==='short'&&!p.publishedRule&&p.use==='private').map(p=>({id:p.id,prompt:p.title,text:p.blocks.filter(b=>b.kind==='prayer').map(b=>b.text).join('\n\n'),route:'#/prayer/'+p.id,sourceId:p.sourceId,locator:p.locator}))].filter(c=>c.text&&c.text.length<6000);
    function drawReview(){const card=cards[reviewIndex%cards.length];root.classList.add('study-tools-page');root.innerHTML='<h1>Review cards</h1><p>Exact published definitions and prayers. Reviewing a card records study activity only.</p>'+(card?`<label>Choose a reading<select id="review-select">${cards.map((c,i)=>`<option value="${i}" ${i===reviewIndex?'selected':''}>${esc(c.prompt)}</option>`).join('')}</select></label><article class="review-card"><p>${reviewIndex+1} / ${cards.length}</p><h2>${esc(card.prompt)}</h2><div id="review-answer" hidden data-scripture-source="${esc(card.sourceId)}"><blockquote>${String(card.text).split(/\n\s*\n/).map(text=>'<p>'+esc(text).replace(/\n/g,'<br>')+'</p>').join('')}</blockquote><p>${esc((sources instanceof Map?sources.get(card.sourceId):sources.find(s=>s.id===card.sourceId))?.title||'')} · ${esc(card.locator)}</p><a href="${card.route}">Open original entry and sources</a></div><div class="tool-actions"><button id="reveal-review">Show text</button><button id="remember-review" hidden>Reviewed</button><button id="next-review">Next</button></div></article>`:'<p>No eligible quotation cards available.</p>');}
    on('input',event=>{if(event.target.id==='notebook-search'){query=event.target.value;root.querySelector('#notebook-items').innerHTML=items();}});on('change',event=>{if(event.target.id==='review-select'){reviewIndex=Number(event.target.value);drawReview();}});
    on('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.notebookTab){tab=button.dataset.notebookTab;draw();}if(button.dataset.removeItem){get()[tab]=get()[tab].filter(item=>item.id!==button.dataset.removeItem);save();draw();}if(button.dataset.answer){const item=get().questions.find(q=>q.id===button.dataset.answer);item.answered=!item.answered;save();draw();}if(button.hasAttribute('data-new-question'))addQuestion('#/notebook','General question');if(button.id==='reveal-review'){root.querySelector('#review-answer').hidden=false;root.querySelector('#remember-review').hidden=false;button.hidden=true;}if(button.id==='remember-review'){const card=cards[reviewIndex],prior=get().reviews[card.id]||{count:0};get().reviews[card.id]={lastReviewed:date(),nextReview:new Date(Date.now()+86400000*Math.min(30,2**Math.min(prior.count,5))).toISOString(),count:prior.count+1};save();reviewIndex=(reviewIndex+1)%cards.length;drawReview();}if(button.id==='next-review'){reviewIndex=(reviewIndex+1)%cards.length;drawReview();}});draw();return ()=>{abort.abort();root.classList.remove('study-tools-page');};
  }
  return {connect,get,snapshot,sanitize,validate,replace,save,mount,enhance,dialog,hash,blank};
})();
